INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8601, '1 Kings 12:8', '1 Kings', 12, 8, '&nbsp;خو هغۀ د مشرانو نصيحت رد کړو او هغه زلمو له لاړو کوم چې د هغۀ سره لوئ شوى وُو او اوس د هغۀ مشوره ورکوونکى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8602, '1 Kings 12:9', '1 Kings', 12, 9, '&nbsp;هغۀ ترې نه تپوس وکړو، ”تاسو ما له مشوره راکړئ چې څۀ وکړُو. مونږ هغه خلقو ته څۀ ووايو چې ما ته وائى چې د هغوئ بوجونه سپک کړم چې زما پلار ورباندې اېښى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8603, '1 Kings 12:10', '1 Kings', 12, 10, '&nbsp;نو زلمو ورته ووئيل، ”څوک چې آسان ژوند غواړى نو هغوئ ته ووايه چې، زما کچه ګوته زما د پلار د ملا نه غټه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8604, '1 Kings 12:11', '1 Kings', 12, 11, '&nbsp;هغوئ ته ووايه چې، زما پلار په تاسو درانۀ بوجونه اچولى دى، خو زۀ به دا نور هم درانۀ کړم. هغۀ تاسو په کوړو وهلئ، خو زۀ به تاسو په لړمانو سم کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8605, '1 Kings 12:12', '1 Kings', 12, 12, '&nbsp;درې ورځې وروستو يربعام او ټول خلق رحُبعام بادشاه ته راواپس شول، لکه څنګه چې دې بادشاه ورته وئيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8606, '1 Kings 12:13', '1 Kings', 12, 13, '&nbsp;بادشاه د مشرانو سړو مشوره رد کړه او خلقو ته يې سختې خبرې وکړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8607, '1 Kings 12:14', '1 Kings', 12, 14, '&nbsp;هم هغه شان څنګه چې زلمو ورته وئيلى وُو. هغۀ ووئيل، ”زما پلار په تاسو باندې درانۀ بوجونه اچولى وُو، خو زۀ به دا نور هم درانۀ کړم. هغۀ تاسو په کوړو باندې وهلئ، خو زۀ به تاسو په لړمانو باندې سموم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8608, '1 Kings 12:15', '1 Kings', 12, 15, '&nbsp;نو بادشاه خلقو ته غوږ ونۀ نيولو، دا هر څۀ ځکه بدل شول چې دا مالِک خُدائ ته منظوره وه چې هغه خبره پوره کړى چې مالِک خُدائ د سيلا پېغمبر اخياه په ذريعه د نباط زوئ يربعام ته کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8609, '1 Kings 12:16', '1 Kings', 12, 16, '&nbsp;کله چې ټول بنى اِسرائيليان پوهه شول چې بادشاه هغوئ ته غوږ نۀ نيولو، نو هغوئ ووئيل، ”مونږ د داؤد بادشاهى نۀ منو، د يَسى په زوئ کښې زمونږ څۀ فائده ده. اے بنى اِسرائيلو، ځئ خپلو خېمو ته واپس لاړ شئ، د داؤد خاندان دې خپله بادشاهى سمباله کړى.“ او بنى اِسرائيليان خپلو خېمو ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8610, '1 Kings 12:17', '1 Kings', 12, 17, '&nbsp;خو رحُبعام په هغه بنى اِسرائيلو باندې بادشاهى کوله کوم چې د يهوداه په علاقه کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8611, '1 Kings 12:18', '1 Kings', 12, 18, '&nbsp;بيا رحُبعام بادشاه ادورام ولېږلو، کوم چې د هغه مزدورانو مشر وو چې په زور کار ترې نه اخستے شو، چې هغه اِسرائيل له لاړ شى، خو هغوئ هغه سنګسار کړو. رحُبعام په تېزۍ سره په خپله جنګى ګاډۍ کښې سور شو او يروشلم ته وتښتېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8612, '1 Kings 12:19', '1 Kings', 12, 19, '&nbsp;نو هم د هغه وخت نه د اِسرائيل خلق د داؤد د شاهى خاندان خِلاف بغاوت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8613, '1 Kings 12:20', '1 Kings', 12, 20, '&nbsp;کله چې اِسرائيليان خبر شول چې يربعام د مِصر نه راواپس شوے دے، نو هغه يې د خلقو يوې غونډې ته راوغوښتلو او د ټول اِسرائيل بادشاه يې جوړ کړو. صِرف د يهوداه قبيلې خلقو د داؤد اولاد منلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8614, '1 Kings 12:21', '1 Kings', 12, 21, '&nbsp;کله چې رحُبعام يروشلم ته ورسېدو، نو هغۀ د يهوداه او بنيامين قبيلې نه يو لاک اتيا زره ښۀ فوجيان راغونډ کړل. هغۀ دا اراده وکړه چې د جنګ دپاره لاړ شى چې د اِسرائيل شمالى قبيلې په خپل قابو کښې بيا راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8615, '1 Kings 12:22', '1 Kings', 12, 22, '&nbsp;خو خُدائ پاک سمعياه پېغمبر ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8616, '1 Kings 12:23', '1 Kings', 12, 23, '&nbsp;چې هغه رحُبعام او د يهوداه او د بنيامين ټولو خلقو ته دا پېغام ورسوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8617, '1 Kings 12:24', '1 Kings', 12, 24, '&nbsp;”په خپلو وروڼو يعنې اِسرائيل باندې حمله مۀ کوئ. ټول کور ته لاړ شئ ځکه چې څۀ وشول نو هغه ما کړى دى.“ هغوئ ټولو د مالِک خُدائ حُکم ومنلو او واپس کورونو ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8618, '1 Kings 12:25', '1 Kings', 12, 25, '&nbsp;د اِسرائيل بادشاه يربعام د اِفرائيم غرونو په مُلک شِکم کښې د پَخو دېوالونو ښار جوړ کړو. بيا هغه لاړو او د فنواېل ښار دپاره يې پاخۀ دېوالونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8619, '1 Kings 12:28', '1 Kings', 12, 28, '&nbsp;د مشورې اخستلو نه پس، بادشاه دوه د سرو زرو سخى جوړ کړل او خپلو خلقو ته يې ووئيل، ”تاسو د ډېرې مودې نه د عبادت دپاره يروشلم ته ځئ. اے اِسرائيليانو، ستاسو خُدايان دا دى چا چې د مِصر مُلک نه راوويستلئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8620, '1 Kings 12:29', '1 Kings', 12, 29, '&nbsp;هغۀ د سرو زرو يو سخے په بيت‌ايل کښې او بل په دان کښې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8621, '1 Kings 12:30', '1 Kings', 12, 30, '&nbsp;نو داسې خلقو ګناه وکړه، ځکه چې هغوئ د عبادت دپاره بيت‌ايل او دان ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8622, '1 Kings 12:31', '1 Kings', 12, 31, '&nbsp;او يربعام په علاقو کښې د عبادت ځايونه هم جوړ کړل او د هغه کورونو نه يې اِمامان خوښ کړل کوم چې د ليوى قبيلې نه نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8623, '1 Kings 12:32', '1 Kings', 12, 32, '&nbsp;يربعام د اتمې مياشتې په پينځلسمه ورځ په يهوداه کښې د اختر په شان يو مذهبى اختر هم مقرر کړو. د سرو زرو کوم سخى يې چې جوړ کړى وُو نو په بيت‌ايل کښې يې په قربان‌ګاه باندې هغې ته نذرانې پېش کړې او هغۀ هلته په بيت‌ايل کښې د عبادت په هغه ځايونو کښې د خِدمت دپاره اِمامان کښېنول کومې علاقائى عبادتخانې چې هغۀ جوړې کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8624, '1 Kings 12:33', '1 Kings', 12, 33, '&nbsp;او د اتمې مياشتې په پينځلسمه ورځ کومه ورځ چې هغۀ په خپله مقرره کړې وه، نو هغه بيت‌ايل ته لاړو او هغۀ چې د اِسرائيليانو دپاره کوم اختر مقرر کړے وو د هغې د مناوولو دپاره هغۀ په قربان‌ګاه باندې يوه نذرانه پېش کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8625, '1 Kings 13:1', '1 Kings', 13, 1, '&nbsp;د مالِک خُدائ په حُکم باندې د يهوداه قبيلې نه د خُدائ پاک يو سړے بيت‌ايل ته لاړو او هلته په هغه وخت ورسېدو چې يربعام نذرانې پېش کولو دپاره د قربان‌ګاه سره ولاړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8626, '1 Kings 13:2', '1 Kings', 13, 2, '&nbsp;د مالِک خُدائ د حُکم په مطابق هغۀ قربان‌ګاه ته مخامخ چغه کړه، ”اے قربان‌ګاه، اے قربان‌ګاه. مالِک خُدائ داسې فرمائى، د داؤد په خاندان کښې به يو ماشوم پېدا شى چې د هغۀ نوم به يوسياه وى. هغه به په تا باندې هغه اِمامان حلال کړى کوم چې په تا باندې نذرانې پېش کوى خو په حقيقت کښې په علاقائى عبادتخانې کښې خِدمت کوى او هغه به درباندې د بنيادمو هډُوکى وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8627, '1 Kings 13:3', '1 Kings', 13, 3, '&nbsp;او پېغمبر خبره جارى وساتله، ”دا قربان‌ګاه به ټوټې ټوټې شى او ايرې به يې خوَرې وَرې شى. نو بيا به تا ته پته ولګى چې مالِک خُدائ زما په ذريعه خبرې کړې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8628, '1 Kings 13:4', '1 Kings', 13, 4, '&nbsp;کله چې يربعام بادشاه دا واورېدل نو هغۀ ورته اِشاره وکړه او حُکم يې ورکړو، ”دا سړے ونيسئ.“ نو د بادشاه لاس سمدستى شل شو او واپس يې راغونډ نۀ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8629, '1 Kings 13:5', '1 Kings', 13, 5, '&nbsp;نو قربان‌ګاه سمدستى ټوټې ټوټې شوه او ايرې په زمکه ورغورزېدې، لکه څنګه چې هغه پېغمبر د مالِک خُدائ په نوم پېشګوئې کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8630, '1 Kings 13:6', '1 Kings', 13, 6, '&nbsp;يربعام بادشاه پېغمبر ته ووئيل، ”مالِک خُدائ ستا خُدائ پاک ته زما دپاره دُعا وکړه او هغۀ ته سوال وکړه چې زما لاس روغ کړى.“ نو پېغمبر مالِک خُدائ ته سوال وکړو او د بادشاه لاس روغ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8631, '1 Kings 13:7', '1 Kings', 13, 7, '&nbsp;بيا بادشاه پېغمبر ته ووئيل، ”ما سره کور ته لاړ شه او روټۍ راسره وخوره. تا چې څۀ کړى دى نو زۀ به د هغې اِنعام درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8632, '1 Kings 13:8', '1 Kings', 13, 8, '&nbsp;خو د خُدائ پاک سړى ورته وفرمائيل، ”کۀ تۀ ما له ستا نيم دولت هم راکړې، نو زۀ به تا سره لاړ نۀ شم او نۀ به هلته ستا نه څۀ وخورم او نۀ وڅښم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8633, '1 Kings 13:9', '1 Kings', 13, 9, '&nbsp;مالِک خُدائ ما له حُکم راکړے دے چې نۀ به څۀ خورې او نۀ څښې او چې په کومه لار راغلے يې په هغې به واپس هم نۀ ځې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8634, '1 Kings 13:10', '1 Kings', 13, 10, '&nbsp;خو چې په کومه لار هغه راغلے وو نو واپس په هغې لا نۀ ړو او په بله لار لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8635, '1 Kings 13:11', '1 Kings', 13, 11, '&nbsp;په هغه وخت کښې يو بوډا پېغمبر چې په بيت‌ايل کښې اوسېدو، د هغۀ زامن راغلل او هغۀ ته يې هغه څۀ ووئيل چې د يهوداه پېغمبر په هغه ورځ په بيت‌ايل کښې څۀ کړى وُو او څۀ يې يربعام بادشاه ته فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8636, '1 Kings 13:12', '1 Kings', 13, 12, '&nbsp;هغه بوډا پېغمبر د هغوئ نه تپوس وکړو، ”کله چې هغه تلو نو په کومه لاره لاړو؟“ نو هغوئ ورته هغه سړک وښودلو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8637, '1 Kings 13:13', '1 Kings', 13, 13, '&nbsp;او هغۀ هغوئ ته ووئيل چې زما دپاره خپل خر کته کړئ. نو هغوئ ورله خر کته کړو او هغه ورباندې سور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8638, '1 Kings 13:14', '1 Kings', 13, 14, '&nbsp;د يهوداه په پېغمبر پسې په هغه سړک روان وو او هغه يې وموندو چې د څېړۍ د ونې لاندې ناست وو. هغۀ ترې نه تپوس وکړو، ”تۀ د يهوداه پېغمبر يې څۀ؟“ هغه سړى جواب ورکړو، ”آو، زۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8639, '1 Kings 13:15', '1 Kings', 13, 15, '&nbsp;نو بوډا پېغمبر هغۀ ته وفرمائيل، ”ما سره کور ته لاړ شه او روټۍ وخوره.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8640, '1 Kings 13:16', '1 Kings', 13, 16, '&nbsp;خو د يهوداه پېغمبر ورته وفرمائيل، ”زۀ تا سره واپس نۀ شم تلے او نۀ په دې ځائ کښې تا سره روټۍ خوړے شم او نۀ اوبۀ څښلے شم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8641, '1 Kings 13:17', '1 Kings', 13, 17, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې تۀ به هلته نۀ روټۍ خورې او نۀ به اوبۀ څښې او چې په کومه لاره تلے يې، نو په هغې به واپس نۀ راځې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8642, '1 Kings 13:18', '1 Kings', 13, 18, '&nbsp;نو د بيت‌ايل بوډا پېغمبر هغۀ ته وفرمائيل، ”زۀ هم ستا په شان پېغمبر يم او د مالِک خُدائ په حُکم ما ته يوې فرښتې وفرمائيل چې د ځان سره دې کور ته بوځم او زۀ ستا مېلمستيا وکړم.“ خو دروغ يې ورته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8643, '1 Kings 13:19', '1 Kings', 13, 19, '&nbsp;نو د يهوداه پېغمبر د هغه بوډا پېغمبر سره کور ته لاړو او د هغۀ سره يې روټۍ وخوړه او اوبۀ يې ورسره وڅښلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8644, '1 Kings 13:20', '1 Kings', 13, 20, '&nbsp;چې کله هغوئ په دسترخوان ناست وُو، نو په هغه بوډا پېغمبر باندې د مالِک خُدائ کلام نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8645, '1 Kings 13:21', '1 Kings', 13, 21, '&nbsp;او هغۀ د يهوداه پېغمبر ته چغه کړه، ”مالِک خُدائ تا ته فرمائى چې تا د هغۀ نافرمانى کړې ده او چې هغۀ څۀ حُکم درکړے وو هغه شان دې ونۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8646, '1 Kings 13:22', '1 Kings', 13, 22, '&nbsp;خو تۀ واپس راغلې او په هغه ځائ کښې دې روټۍ وخوړه او اوبۀ دې وڅښلې چې هغۀ تا ته فرمائيلى وُو چې هلته به خوراک څښاک نۀ کوې. نو په دې وجه تۀ به د پلار نيکۀ په اديره کښې نۀ شې ښخولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8647, '1 Kings 13:23', '1 Kings', 13, 23, '&nbsp;کله چې هغوئ خوراک ختم کړو، نو هغه بوډا پېغمبر د يهوداه پېغمبر دپاره خر کته کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8648, '1 Kings 13:24', '1 Kings', 13, 24, '&nbsp;هغه روان شو. په لار کښې يو زمرے ورباندې راغلو او هغه يې ووژلو. د هغۀ لاش په سړک پروت وو او خر او زمرے ورسره ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8649, '1 Kings 13:25', '1 Kings', 13, 25, '&nbsp;څۀ سړى هلته تېرېدل او په سړک باندې يې لاش وليدو چې زمرے ورسره نزدې ولاړ وو. هغوئ بيت‌ايل ته لاړل او چې څۀ يې ليدلى وُو په هغې باندې يې خلق خبر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8650, '1 Kings 13:26', '1 Kings', 13, 26, '&nbsp;کله چې بوډا پېغمبر د دې نه خبر شو، نو هغۀ وفرمائيل، ”دا هغه پېغمبر دے چې د مالِک خُدائ نافرمانى يې کړې ده. نو دا ځکه مالِک خُدائ زمرے ورولېږلو چې حمله پرې وکړى او مړ يې کړى، لکه څنګه چې مالِک خُدائ فرمائيلى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8651, '1 Kings 13:27', '1 Kings', 13, 27, '&nbsp;بيا هغۀ خپلو زامنو ته وفرمائيل، ”زما دپاره زما خر کته کړئ.“ نو هغوئ هم داسې وکړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8652, '1 Kings 13:28', '1 Kings', 13, 28, '&nbsp;او هغه روان شو او د هغه پېغمبر لاش يې وليدو چې په سړک پروت وو، چې خر او زمرے تر اوسه پورې ورسره ولاړ وُو، ازمرى نۀ لاش خوړلے وو او نۀ يې په خر حمله کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8653, '1 Kings 13:29', '1 Kings', 13, 29, '&nbsp;هغه بوډا پېغمبر لاش راواخستو، په خرۀ يې کېښودو او واپس يې بيت‌ايل ته راوړو چې په دې باندې غم وکړى او ښخ يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8654, '1 Kings 13:30', '1 Kings', 13, 30, '&nbsp;هغه يې د خپل خاندان په قبر کښې ښخ کړو او هغه او د هغۀ زامنو په هغۀ باندې غمژن وُو او وئيل يې چې، ”اے زما وروره ډېر افسوس دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8655, '1 Kings 13:31', '1 Kings', 13, 31, '&nbsp;چې هغه يې ښخ کړو نو پېغمبر خپلو زامنو ته وفرمائيل، ”کله چې زۀ مړ شم، نو ما په هغه قبر کښې ښخ کړئ چې په کوم کښې د خُدائ پاک نبى ښخ دے، او زما لاش د هغۀ د هډوکو په خوا کښې کېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8656, '1 Kings 13:32', '1 Kings', 13, 32, '&nbsp;نو هغۀ چې د مالِک خُدائ په حُکم کومې خبرې په بيت‌ايل کښې د قربان‌ګاه خِلاف او د سامريه په ښارونو کښې د علاقائى عبادتخانې خِلاف کولې نو هغه به خامخا رښتيا شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8657, '1 Kings 13:33', '1 Kings', 13, 33, '&nbsp;خو د اِسرائيل بادشاه يربعام بيا هم د خپلو بدو عملونو نه نۀ اوړېدو او د هر قِسم خلقو اِمامان يې خوښول، چې په هغه علاقائى عبادتخانې کښې خِدمت وکړى چې کومې هغۀ جوړې کړې وې. چې چا هم اِمام جوړېدل غوښتل نو هغه به يې اِمام مقررولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8658, '1 Kings 13:34', '1 Kings', 13, 34, '&nbsp;د دې ګناه په وجه د يربعام بادشاهى ختمه شوه او د زمکې د مخ نه ورکه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8659, '1 Kings 14:1', '1 Kings', 14, 1, '&nbsp;په هغه وخت کښې د يربعام بادشاه زوئ ابياه بيمار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8660, '1 Kings 14:2', '1 Kings', 14, 2, '&nbsp;يربعام خپلې ښځې ته ووئيل، ”خپل مخ پټ کړه چې څوک دې ونۀ پېژنى او سيلا ته لاړه شه چرته چې اخياه پېغمبر اوسيږى، چا چې فرمائيل چې زۀ به د اِسرائيل بادشاه جوړېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8661, '1 Kings 14:3', '1 Kings', 14, 3, '&nbsp;هغۀ له لس غټې او څۀ نرۍ روټۍ او يو منګے شات ورکړه. د هغۀ نه تپوس وکړه چې په هلک باندې به څۀ چل کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8662, '1 Kings 14:4', '1 Kings', 14, 4, '&nbsp;نو هغه په سيلا کښې د اخياه کور ته لاړه. د ډېر عُمر په وجه اخياه ړوند شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8663, '1 Kings 14:5', '1 Kings', 14, 5, '&nbsp;مالِک خُدائ اخياه ته فرمائيلى وُو چې د يربعام ښځه د خپل بيمار زوئ په حقله تپوس کولو له راروانه ده. او مالِک خُدائ اخياه ته وفرمائيل چې څۀ به وائې. کله چې د يربعام ښځه راورسېده، نو هغې داسې ښکاره کړل چې هغه ګنې بل څوک ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8664, '1 Kings 14:6', '1 Kings', 14, 6, '&nbsp;خو چې کله اخياه ته پته ولګېده چې هغه په دروازه باندې راننوځى، نو هغۀ وفرمائيل، ”د يربعام ښځې دننه راشه. تۀ دا ولې ښکاره کوې چې ګنې بل څوک يې؟ ما سره ستا دپاره يو بد خبر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8665, '1 Kings 14:7', '1 Kings', 14, 7, '&nbsp;لاړه شه او يربعام ته ووايه چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک هغۀ ته فرمائى چې ما ستا درجه د نورو خلقو نه اوچته کړه او زما د خلقو بنى اِسرائيلو بادشاه مې جوړ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8666, '1 Kings 14:8', '1 Kings', 14, 8, '&nbsp;د داؤد اولاد نه ما بادشاهى واخستله او تا له مې درکړه. خو تۀ زما د خِدمت کوونکى داؤد په شان نۀ يې، چې هغه زما پوره تابعدار وو، زما حُکمونه يې منل او صِرف هغه څۀ يې کول چې ما ورته وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8667, '1 Kings 14:9', '1 Kings', 14, 9, '&nbsp;تا د هغوئ نه هم لوئې ګناهونه وکړل چې کومو ستا نه مخکښې بادشاهى کوله. تا زۀ رد کړے يم او زما غصه دې راپارولې ده ځکه چې د عبادت دپاره دې بُتان او مجسمې جوړې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8668, '1 Kings 14:10', '1 Kings', 14, 10, '&nbsp;نو د دې په وجه به زۀ ستا په شاهى خاندان وبا راولم او ستا د اولاد ټول نران به ووژنم کۀ هغه آزاد وى او کۀ غلام. او زۀ به ستا د خاندان نه ځان خلاص کړم، هغوئ به داسې فنا شى لکه چې څپياکې وسوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8669, '1 Kings 14:11', '1 Kings', 14, 11, '&nbsp;ستا د خاندان هر يو کس چې په ښار کښې مړ شى نو سپى به هغه وخورى او چې څوک په مېدان کښې مړ شى نو مارغان به هغه وخورى. ما مالِک خُدائ دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8670, '1 Kings 14:12', '1 Kings', 14, 12, '&nbsp;او اخياه د يربعام ښځې ته وفرمائيل، ”اوس واپس کور ته لاړه شه. چې څنګه تۀ ښار ته ورننوځې نو ستا زوئ به مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8671, '1 Kings 14:13', '1 Kings', 14, 13, '&nbsp;ټول بنى اِسرائيليان به په هغۀ ماتم وکړى او ښخ به يې کړى. صِرف دے به د يربعام د خاندان هغه کس وى چې په صحيح طريقه کفن دفن شوے وى، ځکه چې صِرف د هغۀ نه مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک رضا دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8672, '1 Kings 14:14', '1 Kings', 14, 14, '&nbsp;مالِک خُدائ په اِسرائيل باندې يو بادشاه مقرروى چې هغه به د يربعام د خاندان بادشاهى ختمه کړى او دا به هم اوس اوس وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8673, '1 Kings 14:15', '1 Kings', 14, 15, '&nbsp;مالِک خُدائ به د اِسرائيل مُلک له سزا ورکړى او هغه به داسې وخوځوى لکه چې په يوه وَله کښې د لوخې بوټے خوځيږى. هغه به اِسرائيل د دې ښۀ مُلک نه د بېخ نه وباسى کوم چې هغۀ د هغوئ پلار نيکۀ له ورکړ‌ے وو او هغوئ به د فرات سيند نه اخوا خوارۀ وارۀ کړى، ځکه چې هغوئ د اشيرې بُتانو جوړولو په وجه د هغۀ غصه راپارولې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8674, '1 Kings 14:16', '1 Kings', 14, 16, '&nbsp;مالِک خُدائ به اِسرائيل ځکه پرېږدى چې يربعام ګناه کړې ده او اِسرائيل يې د ګناه طرف ته بوتلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8675, '1 Kings 14:17', '1 Kings', 14, 17, '&nbsp;د يربعام ښځه واپس تِرضاه ته لاړه. چې څنګه هغه کور ته دننه شوه نو هغه هلک مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8676, '1 Kings 14:18', '1 Kings', 14, 18, '&nbsp;ټول اِسرائيل په هغۀ پسې غم وکړو او هغه يې ښخ کړو، هم هغه شان چې څنګه مالِک خُدائ د خپل خِدمت کوونکى اخياه پېغمبر په ذريعه فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8677, '1 Kings 14:19', '1 Kings', 14, 19, '&nbsp;يربعام بادشاه چې نور څۀ هم وکړل، هغۀ چې کوم جنګونه کړى وُو او چې هغۀ څنګه بادشاهى کوله نو دا هر څۀ د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8678, '1 Kings 14:20', '1 Kings', 14, 20, '&nbsp;يربعام دوويشت کاله بادشاهى وکړه. هغه مړ شو او ښخ شو او د هغۀ زوئ ندب د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8679, '1 Kings 14:21', '1 Kings', 14, 21, '&nbsp;د سليمان زوئ رحُبعام د يو څلوېښتو کالو وو چې هغه د يهوداه بادشاه جوړ شو او هغۀ اوولس کاله په يروشلم کښې بادشاهى وکړه، دا هغه ښار دے چې مالِک خُدائ د بنى اِسرائيلو ټولې علاقې نه خوښ کړے دے چرته چې د هغۀ عبادت کيږى. د رحُبعام مور نعمه د عمون وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8680, '1 Kings 14:22', '1 Kings', 14, 22, '&nbsp;د يهوداه خلقو د مالِک خُدائ خِلاف ګناه وکړه او د هغۀ غصه يې ځکه راوپاروله چې د خپل پلار نيکۀ نه زياته نافرمانى يې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8681, '1 Kings 14:23', '1 Kings', 14, 23, '&nbsp;هغوئ د غلطو خُدايانو دپاره علاقائى عبادتخانې جوړې کړې او د کاڼو ستنې او د اشيرې بُت نښې يې ولګولې چې په غرونو او د شنو ونو لاندې عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8682, '1 Kings 14:24', '1 Kings', 14, 24, '&nbsp;د دې هر څۀ نه بده خبره دا وه چې هلته سړى او ښځې وې چې د غېرو قومونو د عبادت په ځايونو کښې يې کنجرتوب کولو. د يهوداه خلقو هغه ټول حرام کارونه وکړل کوم چې هغه خلقو کول څوک چې مالِک خُدائ په هغه وخت شړلى وُو چې کله بنى اِسرائيليان په مُلک کښې مخ په وړاندې تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8683, '1 Kings 14:25', '1 Kings', 14, 25, '&nbsp;د رحُبعام د بادشاهۍ په پينځم کال د مِصر بادشاه سيساق په يروشلم حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8684, '1 Kings 14:26', '1 Kings', 14, 26, '&nbsp;هغۀ د مالِک خُدائ د کور او د محل ټولې خزانې يوړلې سره د سرو زرو هغه ډالونو چې سليمان جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8685, '1 Kings 14:27', '1 Kings', 14, 27, '&nbsp;د دې په ځائ رحُبعام بادشاه د زېړو ډالونه جوړ کړل او د هغه آفسرانو په حواله يې کړل کوم چې د محل د دروازو څوکيداران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8686, '1 Kings 14:28', '1 Kings', 14, 28, '&nbsp;هر ځل به چې بادشاه د مالِک خُدائ کور ته تلو، نو څوکيدارانو به ډالونه وړل او بيا به يې واپس د څوکيدارانو کوټې ته راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8687, '1 Kings 14:29', '1 Kings', 14, 29, '&nbsp;نور هر څۀ چې رحُبعام بادشاه کړى وُو نو هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8688, '1 Kings 14:30', '1 Kings', 14, 30, '&nbsp;په دې ټوله موده کښې رحُبعام او يربعام د يو بل خِلاف په جنګ کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8689, '1 Kings 14:31', '1 Kings', 14, 31, '&nbsp;رحُبعام مړ شو او د داؤد د ښار په شاهى اديره کښې ښخ شو. د هغۀ مور نعمه وه. او د رحُبعام زوئ ابياه د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8690, '1 Kings 15:1', '1 Kings', 15, 1, '&nbsp;د يربعام د نباط د زوئ د بادشاهۍ په اتلسم کال، ابياه د يهوداه بادشاه شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8691, '1 Kings 15:2', '1 Kings', 15, 2, '&nbsp;او هغۀ په يروشلم کښې درې کاله بادشاهى وکړه. د هغۀ مور معکه د ابى‌سلوم لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8692, '1 Kings 15:3', '1 Kings', 15, 3, '&nbsp;هغۀ د خپل پلار په شان هم هغه ګناهونه وکړل او د مالِک خُدائ د خپل خُدائ پاک وفادار نۀ وو، لکه څنګه چې د هغۀ نيکۀ داؤد وفادار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8693, '1 Kings 15:4', '1 Kings', 15, 4, '&nbsp;خو مالِک خُدائ د هغۀ خُدائ پاک د داؤد د خاطره ابياه له يو زوئ ورکړو چې د هغۀ نه پس په يروشلم بادشاهى کوى او د دې حِفاظت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8694, '1 Kings 15:5', '1 Kings', 15, 5, '&nbsp;مالِک خُدائ داسې ځکه وکړل چې داؤد به هغه کار کولو چې مالِک خُدائ پرې رضا کېدو او ټول عُمر يې د حِتى اورِياه د مسئلې نه بغېر د هغۀ د يو حُکم نافرمانى نۀ وه کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8695, '1 Kings 15:6', '1 Kings', 15, 6, '&nbsp;کوم جنګ چې د رحُبعام او يربعام په مينځ کښې شروع شوے وو نو هغه د ابياه په ټول ژوند کښې جارى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8696, '1 Kings 15:7', '1 Kings', 15, 7, '&nbsp;او نور هر څۀ چې ابياه کړى وُو هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8697, '1 Kings 15:8', '1 Kings', 15, 8, '&nbsp;ابياه مړ شو او د داؤد په ښار کښې ښخ شو او د هغۀ زوئ آسا د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8698, '1 Kings 15:9', '1 Kings', 15, 9, '&nbsp;د اِسرائيلو د بادشاه د يربعام د بادشاهۍ په شلم کال آسا د يهوداه بادشاه شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8699, '1 Kings 15:10', '1 Kings', 15, 10, '&nbsp;او هغۀ يو څلوېښت کاله په يروشلم کښې بادشاهى وکړه. د هغۀ نيا معکه وه، چې د ابى‌سلوم لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8700, '1 Kings 15:11', '1 Kings', 15, 11, '&nbsp;آسا د خپل پلار نيکۀ داؤد په شان هم هغه څۀ کول چې مالِک خُدائ ورباندې رضا کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');